<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'../../api';import ProductCard from'../../components/ProductCard.vue';import{useCartStore}from'../../stores/cart';import type{Category,Product}from'../../types';const active=ref('all'),keyword=ref(''),categories=ref<Category[]>([]),products=ref<Product[]>([]),cart=useCartStore();async function load(){const h=await api.home();categories.value=h.categories;products.value=await api.products(active.value,keyword.value)}onShow(async()=>{await cart.load();await load()});async function pick(id:string){active.value=id;await load()}const open=(id:string)=>uni.navigateTo({url:`/pages/product/detail?id=${id}`})</script>
<template><view class="page"><view class="search card"><input v-model="keyword" placeholder="今天想吃什么？" confirm-type="search" @confirm="load"/><button @tap="load">搜索</button></view><scroll-view scroll-x class="tabs"><view class="tabs__inner"><view v-for="c in categories" :key="c.id" class="tab" :class="{'tab--active':active===c.id}" @tap="pick(c.id)">{{c.name}}</view></view></scroll-view><view class="result"><text class="result__title">{{categories.find(c=>c.id===active)?.name||'全部商品'}}</text><text class="muted">{{products.length}} 件可送到寝</text></view><view class="grid"><ProductCard v-for="p in products" :key="p.id" :product="p" :quantity="cart.quantity(p.id)" @add="cart.set($event,cart.quantity($event.id)+1)" @open="open"/></view></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.search{height:88rpx;display:flex;align-items:center;padding:0 12rpx 0 26rpx}.search input{flex:1;font-size:28rpx}.search button{margin:0;background:$ink;color:#fff;border-radius:24rpx;font-size:24rpx}.tabs{white-space:nowrap;margin:28rpx 0}.tabs__inner{display:flex;gap:12rpx}.tab{padding:18rpx 30rpx;border-radius:26rpx;background:#fff;border:2rpx solid $line;font-weight:700}.tab--active{background:$primary;color:#fff;border-color:$primary}.result{display:flex;align-items:baseline;justify-content:space-between;margin:26rpx 0}.result__title{font-size:38rpx;font-weight:900}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22rpx}</style>
